demos=[(8,8,[((0,4),9,2),((1,1),8,8),((2,4),0,5),((3,1),3,2),((4,7),0,8),((5,0),9,5),((6,4),8,2),((7,0),1,8)]),(6,6,[((0,1),6,2),((2,3),5,8),((3,5),4,5),((4,3),3,2),((5,0),5,8)]),(6,12,[((0,2),3,8),((0,7),6,8),((0,9),9,2),((2,0),9,2),((2,8),5,5),((4,3),0,5),((5,5),8,2),((5,10),4,8)])]
cls={2:0,8:1,5:2}
# Search modular linear class formulas
features={'r':lambda r,c,v,h,w:r,'c':lambda r,c,v,h,w:c,'v':lambda r,c,v,h,w:v,'h':lambda r,c,v,h,w:h,'w':lambda r,c,v,h,w:w,'idx':lambda r,c,v,h,w:r*w+c,'one':lambda r,c,v,h,w:1}
sol=[]
import itertools
for mod in range(3,31):
 for names in itertools.product(features, repeat=3):
  # linear combination of 3 features coefficients 0..mod-1 too big. do 1 feature and affine v/r/c coefficients modulo3 target
  pass
for mod in range(3,31):
 for names in [('r','c','v','one'),('idx','v','one'),('r','c','one'),('c','v','one'),('r','v','one')]:
  fs=[features[n] for n in names]
  for co in itertools.product(range(mod),repeat=len(names)):
   if all((sum(a*f(r,c,v,h,w) for a,f in zip(co,fs))%mod)%3==cls[o] for h,w,pts in demos for (r,c),v,o in pts):
    sol.append((mod,names,co))
len(sol),sol[:20]
